'use strict';

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const CHAT_ID_RE = /^-?\d+$/;
const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;
const HASH_RE = /^[0-9a-f]{32}$/i;
const SPHERES = Object.freeze({
  health: { position: 1 },
  energy: { position: 2 },
  mood: { position: 3 },
  calm: { position: 4 },
  clarity: { position: 5 },
  motivation: { position: 6 },
  relationships: { position: 7 },
  progress: { position: 8 },
  inspiration: { position: 9 },
  finance: { position: 10 }
});
const CHANGE_KINDS = new Set(['effect', 'retract', 'user_score']);
const DURATION_DAYS = new Set([1, 3, 7, 14]);

const clean = (value, limit = 500) => String(value ?? '').trim().slice(0, limit);
const integer = value => {
  const parsed = Number(value);
  return Number.isSafeInteger(parsed) ? parsed : null;
};
const parseObject = value => {
  if (value && typeof value === 'object' && !Array.isArray(value)) return value;
  if (typeof value !== 'string' || !value.trim()) return null;
  try {
    const parsed = JSON.parse(value);
    return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : null;
  } catch {
    return null;
  }
};
const decimalToCents = value => {
  const text = String(value ?? '').trim().replace(',', '.');
  const match = text.match(/^([+-]?)(\d+)(?:\.(\d+))?$/);
  if (!match) return null;
  const fraction = match[3] || '';
  if (fraction.length > 2 && /[1-9]/.test(fraction.slice(2))) return null;
  const whole = Number(match[2]);
  if (!Number.isSafeInteger(whole)) return null;
  const cents = whole * 100 + Number(fraction.slice(0, 2).padEnd(2, '0'));
  return match[1] === '-' ? -cents : cents;
};
const unwrapRows = item => {
  let value = item?.json?.body ?? item?.json ?? {};
  if (typeof value === 'string') {
    try {
      value = JSON.parse(value);
    } catch {
      return [{ _invalidResponse: true }];
    }
  }
  if (Array.isArray(value)) return value;
  if (Array.isArray(value?.data)) return value.data;
  return value && typeof value === 'object' ? [value] : [];
};

const rawRows = $input.all()
  .flatMap(unwrapRows)
  .filter(row => row && typeof row === 'object' && (
    row.notification_id ||
    row.notificationId ||
    row.lease_token ||
    row.leaseToken ||
    row._invalidResponse
  ));

return rawRows.map(raw => {
  const errors = [];
  const payload = parseObject(raw.payload_json ?? raw.payloadJson);
  const notificationId = clean(raw.notification_id ?? raw.notificationId, 80);
  const principalId = clean(raw.principal_id ?? raw.principalId, 200);
  const inputId = clean(raw.input_id ?? raw.inputId, 80);
  const analysisRunId = clean(raw.analysis_run_id ?? raw.analysisRunId, 80);
  const snapshotId = clean(raw.snapshot_id ?? raw.snapshotId, 80);
  const sourceMessageId = clean(raw.source_message_id ?? raw.sourceMessageId, 120);
  const localDate = clean(raw.local_date ?? raw.localDate, 20);
  const telegramChatId = clean(raw.telegram_chat_id ?? raw.telegramChatId, 120);
  const deliveryAddress = clean(raw.delivery_address ?? raw.deliveryAddress, 120);
  const payloadHash = clean(raw.payload_hash ?? raw.payloadHash, 80).toLowerCase();
  const rowCount = integer(raw.row_count ?? raw.rowCount);
  const notificationStatus = clean(raw.notification_status ?? raw.notificationStatus, 40);
  const notificationVersion = integer(raw.notification_version ?? raw.notificationVersion);
  const attemptCount = integer(raw.attempt_count ?? raw.attemptCount);
  const maxAttempts = integer(raw.max_attempts ?? raw.maxAttempts);
  const leaseToken = clean(raw.lease_token ?? raw.leaseToken, 80);
  const leaseUntil = clean(raw.lease_until ?? raw.leaseUntil, 80);

  if (!UUID_RE.test(notificationId)) errors.push('notification_id_invalid');
  if (!principalId) errors.push('principal_id_missing');
  if (!UUID_RE.test(inputId)) errors.push('input_id_invalid');
  if (!UUID_RE.test(analysisRunId)) errors.push('analysis_run_id_invalid');
  if (!UUID_RE.test(snapshotId)) errors.push('snapshot_id_invalid');
  if (!sourceMessageId) errors.push('source_message_id_missing');
  if (!DATE_RE.test(localDate)) errors.push('local_date_invalid');
  if (!CHAT_ID_RE.test(telegramChatId)) errors.push('telegram_chat_id_invalid');
  if (!deliveryAddress) errors.push('delivery_address_missing');
  if (!HASH_RE.test(payloadHash)) errors.push('payload_hash_invalid');
  if (rowCount === null || rowCount < 1 || rowCount > 50) errors.push('row_count_invalid');
  if (notificationStatus !== 'leased') errors.push('notification_status_invalid');
  if (notificationVersion === null || notificationVersion < 1) errors.push('notification_version_invalid');
  if (attemptCount === null || attemptCount < 1) errors.push('attempt_count_invalid');
  if (maxAttempts === null || maxAttempts < 1 || maxAttempts > 20) errors.push('max_attempts_invalid');
  if (!UUID_RE.test(leaseToken)) errors.push('lease_token_invalid');
  if (!leaseUntil || Number.isNaN(Date.parse(leaseUntil))) errors.push('lease_until_invalid');

  if (!payload) {
    errors.push('payload_invalid');
  } else {
    if (payload.contractVersion !== 'chelsea_state_change_notification_v1') {
      errors.push('payload_contract_invalid');
    }
    if (clean(payload.principalId, 200) !== principalId) errors.push('payload_principal_mismatch');
    if (clean(payload.inputId, 80) !== inputId) errors.push('payload_input_mismatch');
    if (clean(payload.analysisRunId, 80) !== analysisRunId) errors.push('payload_run_mismatch');
    if (clean(payload.snapshotId, 80) !== snapshotId) errors.push('payload_snapshot_mismatch');
    if (clean(payload.sourceMessageId, 120) !== sourceMessageId) errors.push('payload_message_mismatch');
    if (clean(payload.localDate, 20) !== localDate) errors.push('payload_date_mismatch');
    if (integer(payload.rowCount) !== rowCount) errors.push('payload_row_count_mismatch');
    if (!Array.isArray(payload.rows) || payload.rows.length !== rowCount) {
      errors.push('payload_rows_invalid');
    }
  }

  const seenRowIds = new Set();
  const normalizedRows = [];
  if (Array.isArray(payload?.rows)) {
    payload.rows.forEach((row, index) => {
      const rowErrors = [];
      const rowId = clean(row?.rowId, 120);
      const changeKind = clean(row?.changeKind, 40);
      const sphereCode = clean(row?.sphereCode, 40);
      const deltaCents = decimalToCents(row?.delta);
      const beforeCents = decimalToCents(row?.beforeScore);
      const afterCents = decimalToCents(row?.afterScore);
      const durationDays = integer(row?.durationDays);
      const sphere = SPHERES[sphereCode];

      if (!rowId) rowErrors.push('row_id_missing');
      if (rowId && seenRowIds.has(rowId)) rowErrors.push('row_id_duplicate');
      if (!CHANGE_KINDS.has(changeKind)) rowErrors.push('change_kind_invalid');
      if (!sphere) rowErrors.push('sphere_code_invalid');
      if (integer(row?.spherePosition) !== sphere?.position) rowErrors.push('sphere_position_invalid');
      if (deltaCents === null || deltaCents < -900 || deltaCents > 900) rowErrors.push('delta_invalid');
      if (beforeCents === null || beforeCents < 100 || beforeCents > 1000) rowErrors.push('before_score_invalid');
      if (afterCents === null || afterCents < 100 || afterCents > 1000) rowErrors.push('after_score_invalid');
      if (!DURATION_DAYS.has(durationDays)) rowErrors.push('duration_days_invalid');
      if (
        deltaCents !== null &&
        beforeCents !== null &&
        afterCents !== null &&
        afterCents - beforeCents !== deltaCents
      ) {
        rowErrors.push('delta_score_mismatch');
      }

      if (rowId) seenRowIds.add(rowId);
      if (rowErrors.length) {
        errors.push(`row_${index + 1}:${rowErrors.join(',')}`);
        return;
      }
      normalizedRows.push({
        rowId,
        changeKind,
        sphereCode,
        spherePosition: sphere.position,
        deltaCents,
        beforeCents,
        afterCents,
        durationDays,
        comment: clean(row?.comment, 500),
        sourceOrder: index
      });
    });
  }

  const rowsBySphere = new Map();
  for (const row of normalizedRows) {
    if (!rowsBySphere.has(row.sphereCode)) rowsBySphere.set(row.sphereCode, []);
    rowsBySphere.get(row.sphereCode).push(row);
  }
  for (const [sphereCode, sphereRows] of rowsBySphere) {
    sphereRows.sort((left, right) => left.sourceOrder - right.sourceOrder);
    for (let index = 1; index < sphereRows.length; index += 1) {
      if (sphereRows[index - 1].afterCents !== sphereRows[index].beforeCents) {
        errors.push(`sphere_${sphereCode}:score_chain_break_at_row_${index + 1}`);
      }
    }
    const totalDeltaCents = sphereRows.reduce((sum, row) => sum + row.deltaCents, 0);
    const chainDeltaCents =
      sphereRows[sphereRows.length - 1].afterCents - sphereRows[0].beforeCents;
    if (totalDeltaCents !== chainDeltaCents) {
      errors.push(`sphere_${sphereCode}:delta_chain_mismatch`);
    }
  }

  const claim = {
    notificationId,
    principalId,
    inputId,
    analysisRunId,
    snapshotId,
    sourceMessageId,
    localDate,
    telegramChatId,
    deliveryAddress,
    payloadHash,
    rowCount,
    notificationStatus,
    notificationVersion,
    attemptCount,
    maxAttempts,
    leaseToken,
    leaseUntil,
    rows: normalizedRows
  };
  const valid = errors.length === 0 && normalizedRows.length === rowCount;

  return {
    json: {
      stateChangeNotificationClaim: claim,
      stateChangeNotificationClaimValid: valid,
      stateChangeNotificationClaimErrors: errors.slice(0, 20),
      stateChangeNotificationErrorCode: valid ? '' : 'state_change_notification_claim_invalid',
      stateChangeNotificationContractVersion: 'chelsea_state_change_notification_claim_v1'
    }
  };
});

'use strict';

const input = $input.first()?.json || {};
