const DURATION_DAYS = new Set([1, 3, 7, 14]);
const SPHERES = Object.freeze({
  health: { position: 1, emoji: '🩺', name: 'Здоровье' },
  energy: { position: 2, emoji: '⚡️', name: 'Энергия' },
  mood: { position: 3, emoji: '😊', name: 'Настроение' },
  calm: { position: 4, emoji: '🧘', name: 'Спокойствие' },
  clarity: { position: 5, emoji: '🧠', name: 'Ясность' },
  motivation: { position: 6, emoji: '🔥', name: 'Мотивация' },
  relationships: { position: 7, emoji: '🤝', name: 'Отношения' },
  progress: { position: 8, emoji: '📈', name: 'Прогресс' },
  inspiration: { position: 9, emoji: '✨', name: 'Вдохновлённость' },
  finance: { position: 10, emoji: '💰', name: 'Финансы' }
});

const escapeMarkdownCell = value => String(value ?? '')
  .replace(/\\/g, '\\\\')
  .replace(/\|/g, '\\|')
  .replace(/([*_`\[\]<>])/g, '\\$1')
  .replace(/\r?\n/g, ' ')
  .trim();
const truncateCodePoints = (value, limit) => {
  const chars = Array.from(String(value ?? ''));
  if (chars.length <= limit) return chars.join('');
  if (limit <= 0) return '';
  if (limit === 1) return '…';
  return `${chars.slice(0, limit - 1).join('')}…`;
};
const sanitizeComment = row => {
  if (row.changeKind === 'user_score') return 'прямая оценка пользователя';
  const fallback = row.changeKind === 'retract'
    ? 'пересмотр предыдущего влияния'
    : 'изменение состояния';
  const normalized = String(row.comment || fallback)
    .normalize('NFKC')
    .replace(/[\u0000-\u001f\u007f-\u009f]+/g, ' ')
    .replace(/[«»„“”"'`]+/g, '')
    .replace(/\s+/g, ' ')
    .trim();
  return normalized || fallback;
};
const formatDelta = cents => {
  const value = Number(cents);
  if (!Number.isSafeInteger(value) || value === 0) return '0';
  const sign = value > 0 ? '➕' : '➖';
  const absolute = Math.abs(value);
  const whole = Math.floor(absolute / 100);
  const remainder = absolute % 100;
  if (remainder === 0) return `${sign}${whole}`;
  const decimal = String(remainder).padStart(2, '0').replace(/0$/, '');
  return `${sign}${whole},${decimal}`;
};
const fail = (code, details = []) => [{
  json: {
    ...input,
    stateChangeNotificationReady: false,
    stateChangeNotificationErrorCode: code,
    stateChangeNotificationErrors: details.slice(0, 20),
    stateChangeNotificationMessageVersion: 'chelsea_state_change_notification_message_v3_rich_table_days'
  }
}];

if (input.stateChangeNotificationClaimValid !== true) {
  return fail(
    input.stateChangeNotificationErrorCode || 'state_change_notification_claim_invalid',
    input.stateChangeNotificationClaimErrors
  );
}

const rows = (Array.isArray(claim.rows) ? claim.rows : [])
  .filter(row => (
    Number.isSafeInteger(row?.deltaCents) &&
    row.deltaCents !== 0 &&
    DURATION_DAYS.has(row?.durationDays) &&
    SPHERES[row.sphereCode]
  ))
  .map(row => ({
    ...row,
    comment: sanitizeComment(row)
  }))
  .sort((left, right) => (
    SPHERES[left.sphereCode].position - SPHERES[right.sphereCode].position ||
    Number(left.sourceOrder) - Number(right.sourceOrder)
  ));

if (rows.length === 0) {
  return fail('state_change_notification_no_nonzero_rows');
}

const indicatorLabels = rows.map(row => {
  const sphere = SPHERES[row.sphereCode];
  return `${sphere.emoji} ${sphere.name}`;
});
const dynamics = rows.map(row => formatDelta(row.deltaCents));
const render = commentLimit => {
  const header = '| Показатель | Динамика | Дней | Комментарий |';
  const separator = '|:---|---:|---:|:---|';
  const lines = rows.map((row, index) => {
    const indicator = escapeMarkdownCell(indicatorLabels[index]);
    const dynamic = escapeMarkdownCell(dynamics[index]);
    const days = escapeMarkdownCell(row.durationDays);
    const comment = escapeMarkdownCell(truncateCodePoints(row.comment, commentLimit));
    return `| ${indicator} | ${dynamic} | ${days} | ${comment} |`;
  });
  return ['## Изменения состояния', '', header, separator, ...lines].join('\n');
};

let commentLimit = MAX_COMMENT_CODE_POINTS;
let markdown = render(commentLimit);
while (markdown.length > MAX_RICH_MARKDOWN_LENGTH && commentLimit > 0) {
  commentLimit -= 1;
  markdown = render(commentLimit);
}
if (markdown.length > MAX_RICH_MARKDOWN_LENGTH) {
  return fail('state_change_notification_telegram_limit_exceeded');
}

const sendKey = `state_change:${claim.analysisRunId}`;
const telegramRequestBody = {
  chat_id: claim.telegramChatId,
  rich_message: {
    markdown
  }
};

return [{
  json: {
    ...input,
    stateChangeNotificationReady: true,
    stateChangeNotificationChatId: claim.telegramChatId,
    stateChangeNotificationRichMarkdown: markdown,
    stateChangeNotificationRichMarkdownLength: markdown.length,
    stateChangeNotificationTransport: 'sendRichMessage',
    stateChangeNotificationRenderedRowCount: rows.length,
