    stateChangeNotificationCommentLimit: commentLimit,
    stateChangeNotificationSendKey: sendKey,
    stateChangeNotificationClaimVersion: claim.notificationVersion,
    stateChangeNotificationTelegramRequestBody: telegramRequestBody,
    telegramRequestBody,
